public class Main {
  public static void main(String[] args) throws IOException {
    String s = new BufferedReader(new InputStreamReader(System.in)).readLine().trim();
    int n = s.length(); int[] prev = new int[n + 1];
    for (int i = 1; i <= n; i++) {
      int[] cur = new int[n + 1];
      for (int j = 1; j <= n; j++) {
        if (s.charAt(i - 1) == s.charAt(n - j)) cur[j] = prev[j - 1] + 1;
        else cur[j] = Math.max(cur[j - 1], prev[j]);
      }
      prev = cur;
    }
    System.out.println(n - prev[n]);
  }
}

